import re
rc=lambda s: s.translate(str.maketrans('ACGT','TGCA'))[::-1]

# ORFs both strands, min length
def orfs(s,minaa=30):
    res=[]
    for strand,t in ((1,s),(-1,rc(s))):
        for f in range(3):
            i=f
            while i+3<=len(t):
                if t[i:i+3] in ('ATG',):
                    j=i
                    while j+3<=len(t) and t[j:j+3] not in ('TAA','TAG','TGA'):
                        j+=3
                    if (j-i)//3>=minaa:
                        if strand==1: res.append((i+1,j+2 if j+2<=len(t) else len(t),(j-i)//3,strand,t[i:j]))
                        else:
                            # convert to plus coords
                            res.append((len(t)-j+1,len(t)-i,(j-i)//3,strand,t[i:j]))
                    i=j+3 if j>i else i+3
                else:
                    i+=3
    return res

for o in sorted(orfs(seq,30)):
