# IUPAC simple
def find(pat):
    # pat with W (A/T), N
    res=[]
    L=len(pat)
    for i in range(n-L+1):
        ok=True
        for j,c in enumerate(pat):
            s=seq[i+j]
            if c=='W':
                if s not in 'AT': ok=False;break
            elif c=='N':
                pass
            elif s!=c: ok=False;break
        if ok: res.append(i+1)
    return res
