seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
rc=lambda s: s.translate(str.maketrans('ACGT','TGCA'))[::-1]
n=len(seq)

# 1. Tandem repeat detection allowing ~10% mismatch, period 3..30
def tandem(seq, period, mincopies=3, maxmm=0.15):
    res=[]
    i=0
    while i <= n-period*mincopies:
        unit=seq[i:i+period]
        # extend
        j=i+period; copies=1
        while j+period<=n:
            nm=sum(1 for a,b in zip(seq[j:j+period],unit) if a!=b)
            if nm<=max(1,round(maxmm*period)):
                copies+=1; j+=period
            else: break
        if copies>=mincopies and copies*period>=20:
            res.append((i+1,j,copies,period,unit))
            i=j
        else:
            i+=1
    return res
for p in range(2,31):
    r=tandem(seq,p)
    if r: print('period',p,r)

